const DAY=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];
const COLORS=['blue','purple','orange','green'];
const seed={version:2,tasks:[{id:'t1',title:'Preparar propuesta de lanzamiento',done:false,date:iso(1),priority:'Alta'},{id:'t2',title:'Revisar notas de la reunión',done:true,date:iso(0),priority:'Media'},{id:'t3',title:'Enviar presupuesto final',done:false,date:iso(2),priority:'Alta'}],projects:[{id:'p1',symbol:'◎',name:'Renovación del portafolio',description:'Contenido, sistema visual y publicación.',progress:72},{id:'p2',symbol:'↗',name:'Lanzamiento Q4',description:'Mensajes, calendario y materiales.',progress:45},{id:'p3',symbol:'◇',name:'Ideas para explorar',description:'Experimentos para el próximo ciclo.',progress:18}],events:[{id:'e1',title:'Plan semanal',day:0,start:540,duration:60,color:'orange'},{id:'e2',title:'Trabajo profundo',day:1,start:600,duration:120,color:'blue'},{id:'e3',title:'Revisión de diseño',day:2,start:780,duration:75,color:'purple'},{id:'e4',title:'Reunión de equipo',day:3,start:660,duration:60,color:'green'},{id:'e5',title:'Cierre de la semana',day:4,start:930,duration:45,color:'orange'}],note:{title:'Notas de trabajo',body:'Ideas para esta semana\n\n• Simplificar la propuesta principal\n• Pedir comentarios antes del jueves\n• Reservar tiempo sin reuniones'},trash:[]};
let data=load();let ui={view:localStorage.getItem('luma-view')||'agenda',taskFilter:'all',searchOpen:false};let saveTick;
const app=document.querySelector('#app');
function iso(offset){const d=new Date();d.setDate(d.getDate()+offset);return d.toISOString().slice(0,10)}
function load(){let model;try{const x=JSON.parse(localStorage.getItem('luma-workspace-v2'));model=x?.version===2?x:structuredClone(seed)}catch{model=structuredClone(seed)}model.note??={title:'Notas de trabajo',body:''};if(!Array.isArray(model.note.blocks))model.note.blocks=blockify(model.note.body||'');return model}
function blockify(text){const lines=String(text||'').split('\n');return (lines.length?lines:['']).map(line=>({id:id(),type:line.startsWith('• ')?'bullet':'text',content:line.replace(/^•\s*/, '')}))}
function save(message='Guardado'){localStorage.setItem('luma-workspace-v2',JSON.stringify(data));flashSave(message)}
function flashSave(message){const s=document.querySelector('[data-save-state]');if(s){s.textContent=message;clearTimeout(saveTick);saveTick=setTimeout(()=>s.textContent='Todo guardado',1200)}}
const nav=[['home','⌂','Inicio'],['agenda','▦','Agenda'],['tasks','✓','Tareas'],['projects','◇','Proyectos'],['notes','✎','Notas']];
function render(){app.innerHTML=`<div class="shell">${sidebar()}<div class="mobile-backdrop" data-close-menu></div><main class="main">${topbar()}<div class="content">${view()}</div></main></div>${palette()}${modal()}<div class="toast"></div>`;bind();if(ui.view==='agenda')requestAnimationFrame(()=>{const sc=document.querySelector('.week-scroll');if(sc)sc.scrollLeft=0})}
function sidebar(){const pending=data.tasks.filter(t=>!t.done).length;return `<aside class="sidebar"><div class="brand"><span class="brand-mark">L</span><div>Luma<small>Espacio personal</small></div></div><div class="quick"><button class="primary" data-new>＋ Crear</button><button class="square" data-search aria-label="Buscar">⌕</button></div><div class="nav-label">Espacio</div><nav class="nav">${nav.map(([id,ic,label])=>`<button class="nav-btn ${ui.view===id?'active':''}" data-view="${id}"><span class="nav-icon">${ic}</span>${label}${id==='tasks'?`<span class="nav-count">${pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><button class="nav-btn" data-view="trash"><span class="nav-icon">♲</span>Papelera<span class="nav-count">${data.trash.length}</span></button><button class="nav-btn" data-settings><span class="nav-icon">⚙</span>Ajustes</button></div></aside>`}
function topbar(){const title={home:'Inicio',agenda:'Agenda semanal',tasks:'Tareas',projects:'Proyectos',notes:'Notas',trash:'Papelera'}[ui.view]||'Luma';return `<header class="topbar"><button class="ghost mobile-menu" data-menu>☰</button><span class="page-name">${title}</span><span class="top-date">${new Intl.DateTimeFormat('es',{weekday:'long',day:'numeric',month:'long'}).format(new Date())}</span><div class="top-actions"><span class="top-date" data-save-state>Todo guardado</span><button class="ghost hide-mobile" data-search>⌕ Buscar</button><button class="primary" data-new>＋ Nuevo</button></div></header>`}
function view(){return ({home:dashboard,agenda, tasks, projects, notes,trash})[ui.view]?.()||dashboard()}
function dashboard(){const todo=data.tasks.filter(t=>!t.done);const next=[...data.events].sort((a,b)=>a.day-b.day||a.start-b.start).slice(0,4);return `<div class="view-head"><div><div class="eyebrow">Panel de hoy</div><h1>Tu trabajo, en orden</h1><p>Prioridades, agenda y progreso sin cambiar de contexto.</p></div><div class="head-actions"><button class="ghost" data-view="agenda">Ver agenda</button></div></div><div class="metrics"><div class="metric"><strong>${todo.length}</strong><span>tareas pendientes</span></div><div class="metric"><strong>${data.events.length}</strong><span>bloques esta semana</span></div><div class="metric"><strong>${avgProgress()}%</strong><span>avance medio</span></div></div><div class="dashboard-grid"><section class="panel"><h2>Siguientes tareas</h2><div class="list">${todo.slice(0,5).map(taskRowMini).join('')||empty('No tienes tareas pendientes.')}</div></section><section class="panel"><h2>Próximos bloques</h2><div class="list">${next.map(e=>`<div class="list-row"><span class="nav-icon">${DAY[e.day]}</span><div><strong>${esc(e.title)}</strong><div class="top-date">${clock(e.start)} · ${e.duration} min</div></div><button class="icon-action" data-view="agenda">›</button></div>`).join('')||empty('Tu semana está libre.')}</div></section></div>`}
function agenda(){const dates=weekDates();return `<div class="view-head"><div><div class="eyebrow">Planificación</div><h1>Semana actual</h1><p>Arrastra los bloques para moverlos. Usa el borde inferior para cambiar su duración.</p></div><div class="head-actions"><button class="primary" data-add-event>＋ Bloque</button></div></div><section class="agenda-shell"><div class="week-scroll"><div class="week"><div class="week-head"><div></div>${DAY.map((d,i)=>`<div class="day-head ${sameDay(dates[i],new Date())?'today':''}"><span>${d}</span><strong>${dates[i].getDate()}</strong></div>`).join('')}</div><div class="week-body"><div class="time-rail">${Array.from({length:13},(_,i)=>`<span class="hour" style="top:${i*72}px">${String(i+8).padStart(2,'0')}:00</span>`).join('')}</div><div class="day-columns">${DAY.map((_,day)=>`<div class="day-col" data-day="${day}">${data.events.filter(e=>e.day===day).map(eventCard).join('')}</div>`).join('')}</div></div></div></div><div class="drag-hint">Consejo: también puedes hacer clic en cualquier hueco para crear un bloque exactamente ahí.</div></section>`}
function eventCard(e){const top=(e.start-480)*1.2,height=Math.max(30,e.duration*1.2);return `<article class="event ${e.color}" data-event="${e.id}" style="top:${top}px;height:${height}px"><button class="event-delete" data-edit-event="${e.id}" aria-label="Editar bloque">•••</button><div class="event-title">${esc(e.title)}</div><div class="event-time">${clock(e.start)}–${clock(e.start+e.duration)}</div><div class="resize" data-resize="${e.id}"></div></article>`}
function tasks(){let rows=data.tasks.filter(t=>ui.taskFilter==='all'||(ui.taskFilter==='open'?!t.done:t.done));return `<div class="view-head"><div><div class="eyebrow">Ejecución</div><h1>Tareas</h1><p>Edita el texto, cambia la fecha o marca el trabajo terminado.</p></div><button class="primary" data-add-task>＋ Tarea</button></div><div class="task-toolbar"><select class="filter" data-task-filter><option value="all" ${ui.taskFilter==='all'?'selected':''}>Todas</option><option value="open" ${ui.taskFilter==='open'?'selected':''}>Pendientes</option><option value="done" ${ui.taskFilter==='done'?'selected':''}>Completadas</option></select></div><section class="task-table"><div class="task-row header"><span></span><span>Tarea</span><span>Fecha</span><span>Prioridad</span><span></span></div>${rows.map(taskRow).join('')||empty('No hay tareas en esta vista.')}</section>`}
function taskRow(t){return `<div class="task-row"><input class="check" type="checkbox" data-task-check="${t.id}" ${t.done?'checked':''}><input class="task-title ${t.done?'done':''}" value="${attr(t.title)}" data-task-title="${t.id}"><input class="date-input" type="date" value="${t.date||''}" data-task-date="${t.id}"><span class="badge ${t.priority.toLowerCase()}">${t.priority}</span><button class="icon-action" data-delete-task="${t.id}" aria-label="Eliminar">×</button></div>`}
function taskRowMini(t){return `<label class="list-row"><input class="check" type="checkbox" data-task-check="${t.id}"><span>${esc(t.title)}</span><span class="badge ${t.priority.toLowerCase()}">${t.priority}</span></label>`}
function projects(){return `<div class="view-head"><div><div class="eyebrow">Progreso</div><h1>Proyectos</h1><p>Mueve el control de avance para mantener cada proyecto al día.</p></div><button class="primary" data-add-project>＋ Proyecto</button></div><section class="projects">${data.projects.map(p=>`<article class="project"><div class="project-top"><span class="project-symbol">${p.symbol}</span><button class="icon-action" data-delete-project="${p.id}" aria-label="Eliminar">×</button></div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="progress-line"><span style="width:${p.progress}%"></span></div><div class="project-meta"><span>Progreso</span><strong>${p.progress}%</strong></div><input class="range" type="range" min="0" max="100" value="${p.progress}" data-project-progress="${p.id}"></article>`).join('')||empty('Crea tu primer proyecto.')}</section>`}
function notes(){return `<div class="view-head"><div><div class="eyebrow">Documento</div><h1>Editor por bloques</h1><p>Escribe / en un bloque vacío o usa Insertar para añadir contenido.</p></div><span class="save-note" data-note-state>Guardado automáticamente</span></div><article class="note-paper"><input class="note-title" value="${attr(data.note.title)}" data-note-title><div class="format-bar" role="toolbar" aria-label="Formato de texto"><button data-format="bold" title="Negrita"><b>B</b></button><button data-format="italic" title="Cursiva"><i>I</i></button><button data-format="underline" title="Subrayado"><u>U</u></button><button data-format="link" title="Crear enlace">↗ Enlace</button><button class="insert-main" data-insert-menu>＋ Insertar bloque</button></div><div class="notion-editor" data-blocks>${data.note.blocks.map(blockHtml).join('')}</div><button class="add-last" data-add-block="text">＋ Escribe algo o pulsa / para ver comandos</button></article><div class="slash-menu hidden" data-slash-menu>${blockCommands()}</div>`}
function blockHtml(b){if(b.type==='divider')return `<div class="note-block divider-block" data-block="${b.id}"><span class="block-grip">⠿</span><hr><button class="block-delete" data-delete-block="${b.id}">×</button></div>`;if(b.type==='table'){const rows=b.rows||[['',''],['','']];return `<div class="note-block table-block" data-block="${b.id}"><span class="block-grip">⠿</span><table><tbody>${rows.map((r,ri)=>`<tr>${r.map((c,ci)=>`<td contenteditable="true" data-table-cell="${b.id}" data-row="${ri}" data-cell="${ci}">${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table><button class="table-add" data-table-row="${b.id}">＋ fila</button><button class="block-delete" data-delete-block="${b.id}">×</button></div>`}const tag=b.type==='h1'?'h2':b.type==='h2'?'h3':'div',prefix=b.type==='bullet'?'<span class="bullet">•</span>':b.type==='todo'?`<input class="check" type="checkbox" data-block-check="${b.id}" ${b.checked?'checked':''}>`:b.type==='callout'?'<span class="callout-icon">💡</span>':'';return `<div class="note-block type-${b.type}" data-block="${b.id}"><span class="block-grip">⠿</span>${prefix}<${tag} class="block-content" contenteditable="true" data-block-content="${b.id}" data-placeholder="Escribe / para insertar…">${b.html?safeRich(b.html):esc(b.content||'')}</${tag}><button class="block-delete" data-delete-block="${b.id}" aria-label="Eliminar bloque">×</button></div>`}
function blockCommands(){return `<button data-add-block="text"><span>¶</span><b>Texto</b><small>Párrafo sencillo</small></button><button data-add-block="h1"><span>H1</span><b>Título</b><small>Encabezado principal</small></button><button data-add-block="h2"><span>H2</span><b>Subtítulo</b><small>Encabezado secundario</small></button><button data-add-block="bullet"><span>•</span><b>Lista</b><small>Lista con viñetas</small></button><button data-add-block="todo"><span>☐</span><b>Tarea</b><small>Casilla dentro del documento</small></button><button data-add-block="quote"><span>❝</span><b>Cita</b><small>Destaca una frase</small></button><button data-add-block="callout"><span>💡</span><b>Aviso</b><small>Bloque destacado</small></button><button data-add-block="link"><span>↗</span><b>Enlace</b><small>Texto con vínculo</small></button><button data-add-block="table"><span>▦</span><b>Tabla</b><small>Tabla editable 2 × 2</small></button><button data-add-block="divider"><span>―</span><b>Separador</b><small>Divide secciones</small></button>`}
function trash(){return `<div class="view-head"><div><div class="eyebrow">Archivo</div><h1>Papelera</h1><p>Puedes restaurar elementos eliminados o vaciar la papelera.</p></div>${data.trash.length?'<button class="ghost danger" data-empty-trash>Vaciar</button>':''}</div><section class="panel"><div class="list">${data.trash.map(x=>`<div class="list-row"><span class="nav-icon">${x.type==='task'?'✓':x.type==='project'?'◇':'▦'}</span><div><strong>${esc(x.item.title||x.item.name)}</strong><div class="top-date">${labelType(x.type)}</div></div><button class="ghost" data-restore="${x.id}">Restaurar</button></div>`).join('')||empty('La papelera está vacía.')}</div></section>`}
function palette(){return `<div class="search-overlay ${ui.searchOpen?'':'hidden'}" data-search-overlay><div class="palette"><input data-search-input placeholder="Buscar tareas, proyectos, notas y bloques…"><div class="results" data-results></div></div></div>`}
function modal(){return `<dialog data-modal><form data-form><div class="modal-head"><h2 data-modal-title>Nuevo elemento</h2><button type="button" class="icon-action" data-close-modal aria-label="Cerrar">×</button></div><div class="modal-body" data-modal-body></div><div class="modal-actions"><button type="button" class="ghost" data-close-modal>Cancelar</button><button type="submit" class="primary" data-submit>Guardar</button></div></form></dialog>`}
function bind(){
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('[data-search]').forEach(b=>b.onclick=openSearch);document.querySelectorAll('[data-new]').forEach(b=>b.onclick=openNew);document.querySelector('[data-menu]')?.addEventListener('click',()=>toggleMenu(true));document.querySelector('[data-close-menu]')?.addEventListener('click',()=>toggleMenu(false));document.querySelector('[data-add-event]')?.addEventListener('click',()=>openEvent());document.querySelector('[data-add-task]')?.addEventListener('click',openTask);document.querySelector('[data-add-project]')?.addEventListener('click',openProject);document.querySelector('[data-settings]')?.addEventListener('click',openSettings);document.querySelector('[data-task-filter]')?.addEventListener('change',e=>{ui.taskFilter=e.target.value;render()});
 document.querySelectorAll('[data-task-check]').forEach(x=>x.onchange=()=>{const t=data.tasks.find(t=>t.id===x.dataset.taskCheck);if(!t)return;t.done=x.checked;save();x.closest('.task-row,.list-row')?.querySelector('.task-title')?.classList.toggle('done',x.checked);const count=document.querySelector('.nav-btn[data-view="tasks"] .nav-count');if(count)count.textContent=data.tasks.filter(t=>!t.done).length;if(ui.taskFilter!=='all')render()});
 document.querySelectorAll('[data-task-title]').forEach(x=>x.onchange=()=>updateTask(x.dataset.taskTitle,{title:x.value.trim()||'Sin título'}));document.querySelectorAll('[data-task-date]').forEach(x=>x.onchange=()=>updateTask(x.dataset.taskDate,{date:x.value}));document.querySelectorAll('[data-delete-task]').forEach(b=>b.onclick=()=>confirmRemove('task',b.dataset.deleteTask));document.querySelectorAll('[data-delete-project]').forEach(b=>b.onclick=()=>confirmRemove('project',b.dataset.deleteProject));document.querySelectorAll('[data-edit-event]').forEach(b=>b.onclick=e=>{e.stopPropagation();openEvent(data.events.find(x=>x.id===b.dataset.editEvent))});
 document.querySelectorAll('[data-project-progress]').forEach(x=>x.oninput=()=>{const p=data.projects.find(p=>p.id===x.dataset.projectProgress);p.progress=+x.value;save();x.closest('.project').querySelector('.progress-line span').style.width=x.value+'%';x.closest('.project').querySelector('.project-meta strong').textContent=x.value+'%'});document.querySelector('[data-note-title]')?.addEventListener('input',e=>{data.note.title=e.target.value;noteSave()});
 document.querySelectorAll('[data-block-content]').forEach(el=>{el.onfocus=()=>ui.activeBlock=el.dataset.blockContent;el.oninput=()=>{const b=data.note.blocks.find(b=>b.id===el.dataset.blockContent);if(!b)return;b.content=el.innerText;b.html=el.innerHTML;if(b.content.trim()==='/'){ui.blockAfter=b.id;showBlockMenu(el)}else{hideBlockMenu();noteSave()}}});document.querySelectorAll('[data-block-check]').forEach(x=>x.onchange=()=>{const b=data.note.blocks.find(b=>b.id===x.dataset.blockCheck);b.checked=x.checked;save()});document.querySelectorAll('[data-table-cell]').forEach(c=>c.oninput=()=>{const b=data.note.blocks.find(b=>b.id===c.dataset.tableCell);b.rows[+c.dataset.row][+c.dataset.cell]=c.innerText;noteSave()});document.querySelectorAll('[data-delete-block]').forEach(b=>b.onclick=()=>deleteNoteBlock(b.dataset.deleteBlock));document.querySelectorAll('[data-table-row]').forEach(b=>b.onclick=()=>{const x=data.note.blocks.find(x=>x.id===b.dataset.tableRow);x.rows.push(Array(x.rows[0].length).fill(''));save();render()});document.querySelectorAll('[data-add-block]').forEach(b=>b.onclick=()=>addNoteBlock(b.dataset.addBlock));document.querySelector('[data-insert-menu]')?.addEventListener('click',e=>{ui.blockAfter=null;showBlockMenu(e.currentTarget)});document.querySelectorAll('[data-format]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>applyFormat(b.dataset.format)});
 document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>restore(b.dataset.restore));document.querySelector('[data-empty-trash]')?.addEventListener('click',()=>openDialog('Vaciar papelera','<p>Esta acción eliminará definitivamente todos los elementos de la papelera.</p>',()=>{data.trash=[];save();render()}));document.querySelectorAll('.day-col').forEach(c=>c.onclick=e=>{if(e.target!==c)return;const rect=c.getBoundingClientRect();const mins=snap((e.clientY-rect.top)/1.2+480);openEvent({day:+c.dataset.day,start:clamp(mins,480,1170)})});document.querySelectorAll('.event').forEach(enableDrag)
}
function go(v){ui.view=v;localStorage.setItem('luma-view',v);ui.searchOpen=false;render()}
function openNew(){if(ui.view==='agenda')openEvent();else if(ui.view==='projects')openProject();else if(ui.view==='notes'){go('notes');setTimeout(()=>document.querySelector('[data-note-body]')?.focus(),0)}else openTask()}
function openDialog(title,body,onSubmit){const d=document.querySelector('[data-modal]'),submit=d.querySelector('[data-submit]');d.querySelector('[data-modal-title]').textContent=title;d.querySelector('[data-modal-body]').innerHTML=body;submit.style.display='';submit.textContent='Guardar';d.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=()=>d.close());const form=d.querySelector('[data-form]');form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;onSubmit(new FormData(form));d.close()};d.showModal();setTimeout(()=>d.querySelector('input,textarea,select')?.focus(),0)}
function openTask(){openDialog('Nueva tarea',`<div class="field"><label>Título</label><input name="title" required placeholder="¿Qué necesitas hacer?"></div><div class="field-row"><div class="field"><label>Fecha</label><input type="date" name="date" value="${iso(0)}"></div><div class="field"><label>Prioridad</label><select name="priority"><option>Alta</option><option selected>Media</option><option>Baja</option></select></div></div>`,f=>{data.tasks.unshift({id:id(),title:f.get('title'),date:f.get('date'),priority:f.get('priority'),done:false});save();go('tasks');toast('Tarea creada')})}
function openProject(){openDialog('Nuevo proyecto',`<div class="field"><label>Nombre</label><input name="name" required placeholder="Nombre del proyecto"></div><div class="field"><label>Descripción</label><textarea name="description" rows="3" placeholder="Resultado que quieres conseguir"></textarea></div><div class="field"><label>Símbolo</label><select name="symbol"><option>◎</option><option>◇</option><option>↗</option><option>✦</option></select></div>`,f=>{data.projects.unshift({id:id(),name:f.get('name'),description:f.get('description'),symbol:f.get('symbol'),progress:0});save();go('projects');toast('Proyecto creado')})}
function openEvent(pref={}){const editing=!!pref.id;openDialog(editing?'Editar bloque':'Nuevo bloque',`<div class="field"><label>Título</label><input name="title" required value="${attr(pref.title||'')}" placeholder="Trabajo profundo, reunión…"></div><div class="field-row"><div class="field"><label>Día</label><select name="day">${DAY.map((d,i)=>`<option value="${i}" ${i===(pref.day??0)?'selected':''}>${d}</option>`).join('')}</select></div><div class="field"><label>Color</label><select name="color">${COLORS.map(c=>`<option value="${c}" ${c===(pref.color||'blue')?'selected':''}>${{blue:'Azul',purple:'Violeta',orange:'Naranja',green:'Verde'}[c]}</option>`).join('')}</select></div></div><div class="field-row"><div class="field"><label>Inicio</label><input type="time" name="start" value="${clock(pref.start??540)}" required></div><div class="field"><label>Duración</label><select name="duration">${[30,45,60,90,120].map(n=>`<option value="${n}" ${n===(pref.duration??60)?'selected':''}>${n<60?n+' min':n===60?'1 hora':n===90?'1 h 30':'2 horas'}</option>`).join('')}</select></div></div>${editing?'<button type="button" class="ghost danger" data-remove-event>Eliminar este bloque</button>':''}`,f=>{const values={title:f.get('title'),day:+f.get('day'),start:toMins(f.get('start')),duration:+f.get('duration'),color:f.get('color')};if(editing)Object.assign(data.events.find(e=>e.id===pref.id),values);else data.events.push({id:id(),...values});save();go('agenda');toast(editing?'Bloque actualizado':'Bloque añadido')});if(editing)document.querySelector('[data-remove-event]').onclick=()=>{document.querySelector('[data-modal]').close();confirmRemove('event',pref.id)}}
function openSettings(){openDialog('Ajustes y datos',`<div class="field"><label>Copias y reinicio</label><button type="button" class="ghost" data-export>Descargar una copia de mis datos</button><button type="button" class="ghost danger" data-reset>Restaurar datos de ejemplo</button></div>`,()=>{});const d=document.querySelector('[data-modal]');d.querySelector('[data-submit]').style.display='none';d.querySelector('[data-export]').onclick=exportData;d.querySelector('[data-reset]').onclick=()=>{if(confirm('¿Restaurar el espacio? Se reemplazarán tus datos actuales.')){data=structuredClone(seed);save();d.close();render()}};d.addEventListener('close',()=>d.querySelector('[data-submit]').style.display='',{once:true})}
function openSearch(){ui.searchOpen=true;document.querySelector('[data-search-overlay]').classList.remove('hidden');const input=document.querySelector('[data-search-input]');drawResults('');input.oninput=()=>drawResults(input.value);setTimeout(()=>input.focus(),0)}
function closeSearch(){ui.searchOpen=false;document.querySelector('[data-search-overlay]')?.classList.add('hidden')}
function drawResults(q){const term=q.toLowerCase().trim(),all=[...data.tasks.map(x=>({label:x.title,type:'Tarea',view:'tasks'})),...data.projects.map(x=>({label:x.name,type:'Proyecto',view:'projects'})),...data.events.map(x=>({label:x.title,type:`${DAY[x.day]} · ${clock(x.start)}`,view:'agenda'})),{label:data.note.title,type:'Nota',view:'notes'}].filter(x=>!term||x.label.toLowerCase().includes(term));document.querySelector('[data-results]').innerHTML=all.slice(0,12).map(x=>`<button class="result" data-result-view="${x.view}"><span>⌕</span><strong>${esc(x.label)}</strong><small>${x.type}</small></button>`).join('')||empty('No se encontraron resultados.');document.querySelectorAll('[data-result-view]').forEach(b=>b.onclick=()=>go(b.dataset.resultView))}
function enableDrag(el){const ev=data.events.find(e=>e.id===el.dataset.event);el.onpointerdown=e=>{if(e.target.closest('button'))return;const resizing=!!e.target.closest('[data-resize]'),x=e.clientX,y=e.clientY,startDay=ev.day,start=ev.start,duration=ev.duration,body=document.querySelector('.day-columns'),w=body.getBoundingClientRect().width/7;el.setPointerCapture(e.pointerId);el.onpointermove=m=>{if(resizing){ev.duration=clamp(snap(duration+(m.clientY-y)/1.2),30,720);el.style.height=(ev.duration*1.2)+'px';el.querySelector('.event-time').textContent=`${clock(ev.start)}–${clock(ev.start+ev.duration)}`}else{ev.day=clamp(startDay+Math.round((m.clientX-x)/w),0,6);ev.start=clamp(snap(start+(m.clientY-y)/1.2),480,1200-ev.duration);el.style.top=((ev.start-480)*1.2)+'px';el.querySelector('.event-time').textContent=`${clock(ev.start)}–${clock(ev.start+ev.duration)}`}};el.onpointerup=()=>{el.onpointermove=null;save('Bloque guardado');render();toast(resizing?'Duración actualizada':'Bloque movido')}}}
function updateTask(id,patch){Object.assign(data.tasks.find(t=>t.id===id),patch);save();render()}
function confirmRemove(type,idv){const key=type==='task'?'tasks':type==='project'?'projects':'events',item=data[key].find(x=>x.id===idv);if(!item)return;openDialog('Mover a la papelera',`<p>¿Quieres mover <strong>${esc(item.title||item.name)}</strong> a la papelera? Podrás restaurarlo después.</p>`,()=>remove(type,idv));const submit=document.querySelector('[data-submit]');submit.textContent='Mover a la papelera';submit.classList.add('danger-fill');document.querySelector('[data-modal]').addEventListener('close',()=>submit.classList.remove('danger-fill'),{once:true})}
function remove(type,idv){const key=type==='task'?'tasks':type==='project'?'projects':'events',idx=data[key].findIndex(x=>x.id===idv);if(idx<0)return;const [item]=data[key].splice(idx,1);data.trash.unshift({id:id(),type,item});save();render();toast('Movido a la papelera')}
function restore(trashId){const i=data.trash.findIndex(x=>x.id===trashId),x=data.trash[i];if(!x)return;data[x.type==='task'?'tasks':x.type==='project'?'projects':'events'].push(x.item);data.trash.splice(i,1);save();render();toast('Elemento restaurado')}
function noteSave(){document.querySelector('[data-note-state]').textContent='Guardando…';clearTimeout(saveTick);saveTick=setTimeout(()=>{save();const s=document.querySelector('[data-note-state]');if(s)s.textContent='Guardado automáticamente'},500)}
function showBlockMenu(anchor){const menu=document.querySelector('[data-slash-menu]');if(!menu)return;const r=anchor.getBoundingClientRect();menu.style.left=Math.min(r.left,innerWidth-300)+'px';menu.style.top=Math.min(r.bottom+8,innerHeight-430)+'px';menu.classList.remove('hidden')}
function hideBlockMenu(){document.querySelector('[data-slash-menu]')?.classList.add('hidden')}
function addNoteBlock(type){const block={id:id(),type,content:''};if(type==='todo')block.checked=false;if(type==='table')block.rows=[['',''],['','']];if(ui.blockAfter){const current=data.note.blocks.find(b=>b.id===ui.blockAfter);if(current?.content?.trim()==='/')current.content='';const i=data.note.blocks.findIndex(b=>b.id===ui.blockAfter);data.note.blocks.splice(i+1,0,block)}else data.note.blocks.push(block);ui.blockAfter=null;save();render();setTimeout(()=>document.querySelector(`[data-block="${block.id}"] [contenteditable]`)?.focus(),0)}
function deleteNoteBlock(blockId){if(data.note.blocks.length===1){data.note.blocks[0].content='';save();render();return}data.note.blocks=data.note.blocks.filter(b=>b.id!==blockId);save();render()}
function applyFormat(format){const el=document.querySelector(`[data-block-content="${ui.activeBlock}"]`);if(!el){toast('Selecciona texto dentro de un bloque');return}if(format==='link'){const url=prompt('Pega la dirección del enlace:','https://');if(!url)return;document.execCommand('createLink',false,url)}else document.execCommand(format,false,null);const b=data.note.blocks.find(b=>b.id===ui.activeBlock);b.content=el.innerText;b.html=el.innerHTML;noteSave()}
function safeRich(html=''){const t=document.createElement('template');t.innerHTML=html;const allowed=new Set(['B','STRONG','I','EM','U','A','BR','DIV','P','SPAN']);[...t.content.querySelectorAll('*')].reverse().forEach(el=>{if(!allowed.has(el.tagName)){el.replaceWith(document.createTextNode(el.textContent||''));return}[...el.attributes].forEach(a=>{if(el.tagName==='A'&&a.name==='href'&&/^https?:\/\//i.test(a.value))return;el.removeAttribute(a.name)});if(el.tagName==='A'&&el.hasAttribute('href')){el.target='_blank';el.rel='noopener'}});return t.innerHTML}
function exportData(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='luma-datos.json';a.click();URL.revokeObjectURL(a.href);toast('Copia descargada')}
function toggleMenu(open){document.querySelector('.sidebar').classList.toggle('open',open);document.querySelector('.mobile-backdrop').classList.toggle('open',open)}
function toast(msg){const t=document.querySelector('.toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1600)}
function empty(msg){return `<div class="empty">${msg}</div>`}function id(){return Math.random().toString(36).slice(2)+Date.now().toString(36)}function snap(n){return Math.round(n/15)*15}function clamp(n,a,b){return Math.max(a,Math.min(b,n))}function clock(min){return `${String(Math.floor(min/60)).padStart(2,'0')}:${String(min%60).padStart(2,'0')}`}function toMins(t){const [h,m]=t.split(':').map(Number);return h*60+m}function esc(s=''){return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]))}function attr(s=''){return esc(s).replace(/'/g,'&#39;')}function avgProgress(){return data.projects.length?Math.round(data.projects.reduce((a,p)=>a+p.progress,0)/data.projects.length):0}function labelType(t){return {task:'Tarea',project:'Proyecto',event:'Bloque de agenda'}[t]}function sameDay(a,b){return a.toDateString()===b.toDateString()}function weekDates(){const now=new Date(),day=(now.getDay()+6)%7,m=new Date(now);m.setHours(0,0,0,0);m.setDate(now.getDate()-day);return DAY.map((_,i)=>{const d=new Date(m);d.setDate(m.getDate()+i);return d})}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'){closeSearch();hideBlockMenu()}});document.addEventListener('click',e=>{if(e.target.matches('[data-search-overlay]'))closeSearch();if(!e.target.closest('[data-slash-menu],[data-insert-menu],[data-block-content]'))hideBlockMenu()});
render();
